struct Team {
    int number;
    int problemsSolved;
    int totalTime;

    Team(int num) : number(num), problemsSolved(0), totalTime(0) {}

    bool operator<(const Team &other) const {
        if (problemsSolved != other.problemsSolved)
            return problemsSolved > other.problemsSolved;
        if (totalTime != other.totalTime)
            return totalTime < other.totalTime;
        return number > other.number; 
    }
};

int main() {
    while (true) {
        int M, T, P, R;
        cin >> M >> T >> P >> R;
        if (M == 0 && T == 0 && P == 0 && R == 0) break;

        vector<Team> teams(T + 1, Team(0));
        for (int i = 1; i <= T; ++i) teams[i].number = i;

        vector<vector<int>> attempts(T + 1, vector<int>(P + 1, 0));
        vector<bool> solved(T + 1);

        for (int i = 0; i < R; ++i) {
            int m, t, p, j;
            cin >> m >> t >> p >> j;
            if (j == 0 && !solved[t]) {
                teams[t].problemsSolved++;
                teams[t].totalTime += m + 20 * attempts[t][p];
                solved[t] = true;
            } else if (j != 0) {
                attempts[t][p]++;
            }
        }

        sort(teams.begin() + 1, teams.end());

        vector<string> ranking;
        for (int i = 1; i <= T; ++i) {
            if (teams[i].problemsSolved > 0) {
                if (ranking.empty() || to_string(teams[i].number) != ranking.back()) {
