bool is_unbalanced(const string& s) {
    if (s.length() < 2) {
        return false;
    }
    map<char, int> counts;
    for (char c : s) {
        counts[c]++;
    }
    int max_count = 0;
    for (auto const& [key, val] : counts) {
        max_count = max(max_count, val);
    }
    return max_count > s.length() / 2;
