            dp[i][2] = (dp[i][2] - dp[i - 1][3] + MOD) % MOD; // G can follow anything except T
            dp[i][3] = (dp[i][3] - dp[i - 1][0] - dp[i - 1][1] + MOD) % MOD; // T can follow anything except A, C
