                                long numGroups = (n - i * f) /j;

                                if (numGroups < c || numGroups > d) continue;
                                long tempWays = 1;

                                tempWays = (tempWays * comb[n][i * f]) % MOD;
                                n -= i * f;
                                for(int x = 0; x < f; x++){
