    x %= MOD;
    while (y) {
        if (y & 1) ret = (ret * x) % MOD;
        y >>= 1;
        x = (x * x) % MOD;
    }
    return ret;
}

long long C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return (((fact[n] * inv[k]) % MOD) * inv[n - k]) % MOD;
}

