import re

def analyze_programs(s1, s2):
    if s1 == s2:
        return "IDENTICAL"

    literals1 = re.findall(r'"(.*?)"', s1)
    literals2 = re.findall(r'"(.*?)"', s2)

    if len(literals1) != len(literals2):
        return "DIFFERENT"

    close_count = 0
    for lit1, lit2 in zip(literals1, literals2):
        if lit1 != lit2:
            close_count += 1

    if close_count == 1:
        return "CLOSE"

    return "DIFFERENT"

