    input_lines = sys.stdin.read().strip().splitlines()
    results = []

    for i in range(0, len(input_lines) - 1, 2):
        s1 = input_lines[i]
        s2 = input_lines[i + 1]
        result = analyze_programs(s1, s2)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

