long long countWays(vector<int>& cards, int N, int A) {
    long long dp[1 << N];
    memset(dp, 0, sizeof(dp));
    dp[0] = 1; // base case

    for (int i = 0; i < N; ++i) {
        for (int mask = (1 << i) - 1; mask >= 0; --mask) {
            dp[mask | (1 << i)] += dp[mask];
        }
    }

    long long totalWays = 0;

    for (int mask = 1; mask < (1 << N); ++mask) {
        int sum = 0, count = 0;
        for (int j = 0; j < N; ++j) {
            if (mask & (1 << j)) {
                sum += cards[j];
                count++;
            }
        }
        if (count > 0 && sum == count * A) {
            totalWays += dp[mask];
        }
    }

    return totalWays;
}

